def sha(p):return hashlib.sha256(p.read_bytes().replace(b'\r\n',b'\n')).hexdigest()
def docx(text,path):
 d=Document();s=d.sections[0];s.top_margin=Inches(.7);s.bottom_margin=Inches(.7);s.left_margin=Inches(.78);s.right_margin=Inches(.78);d.styles['Normal'].font.name='Aptos';d.styles['Normal'].font.size=Pt(10.5);d.styles['Title'].font.name='Aptos Display';d.styles['Title'].font.size=Pt(21);d.styles['Title'].font.color.rgb=RGBColor(0,0,0)
 p=d.add_paragraph(style='Title');p.alignment=WD_ALIGN_PARAGRAPH.CENTER;p.add_run('Operational Readiness Evidence Boundaries in Tactical and Public Safety Workforces')
 d.add_paragraph('Evidence-informed integrative synthesis | Version 1.3 final scientific freeze | 2026-10-10').alignment=WD_ALIGN_PARAGRAPH.CENTER
 for line in text.splitlines():
  if line.startswith('# ') or line.startswith('**Working') or not line.strip():continue
  if line.startswith('## '):d.add_heading(line[3:],1)
  elif re.match(r'^\d+\. ',line):
   p=d.add_paragraph();p.paragraph_format.left_indent=Inches(.22);p.paragraph_format.first_line_indent=Inches(-.22);p.add_run(line)
  else:
   p=d.add_paragraph(line.replace('**',''));p.paragraph_format.space_after=Pt(6)
 d.save(path)
 with zipfile.ZipFile(path) as z:assert z.testzip() is None and 'word/document.xml' in z.namelist()
def sentences(md):
 out=[];section='Front matter';i=0
 for line in md.split('## References')[0].splitlines():
  if line.startswith('## '):section=line[3:];continue
  if not line.strip() or line.startswith('#') or line.startswith('**'):continue
  for x in re.split(r'(?<=[.!?])\s+(?=[A-Z])',line.strip()):
   if x:i+=1;out.append((f'INT13-S{i:03d}',section,x))
 return out
def main():
 md=(SRC/'International_v1.2-FINAL-SCIENTIFIC-AUDIT.md').read_text(encoding='utf-8')
 md=md.replace('Version 1.2 final scientific-audit draft','Version 1.3 final scientific freeze')
 md=md.replace('This working manuscript is designed for final scientific and reference audit; all newly approved expansion claims remain Claim-Ready NO.','This final scientific freeze records the newly approved expansion claims as Claim-Ready YES after named human adjudication; that status does not substitute for future editorial or implementation review.')
 old1486='''The new academy studies add a more specific interpretation of physical readiness than a generic fitness label can provide. In a prospective police-recruit validation study, baseline fitness was examined in relation to academy performance, but the result is best treated as an observed association in a defined recruitment and training environment rather than as a deployment threshold [21]. A second recruit cohort found that push-up capacity and estimated VO2max from run time predicted successful academy graduation in its reported models [22]. These results support the limited proposition that entry fitness can be informative for academy-related outcomes in the sampled systems. They do not establish that a screening test causes graduation, that any cutoff should be transferred between academies, or that academy success is equivalent to field readiness.'''
 new1486='''The new academy studies add a more specific interpretation of physical readiness than a generic fitness label can provide. In a prospective cohort of 724 police recruits from 15 Massachusetts academies (661 graduates and 63 non-graduates), lower entry-level muscular-endurance and aerobic-fitness performance was associated with higher odds of academy non-graduation after adjustment for age, sex, and body mass index: OR 9.6 (95% CI 3.5–26.3) for ≤15 versus 41–60 sit-ups, OR 6.7 (95% CI 2.5–17.5) for ≤20 versus 41–60 push-ups, and OR 18.4 (95% CI 6.8–50.2) for a >15 min 20 s versus 10 min 37 s–12 min 33 s 1.5-mile run [21]. This observational association does not establish that higher fitness causes academy completion, predicts subsequent occupational performance, or supplies thresholds for other agencies or Brazilian policing. A second recruit cohort found that push-up capacity and estimated VO2max from run time predicted successful academy graduation in its reported models [22]. These results support the limited proposition that entry fitness can be informative for academy-related outcomes in the sampled systems. They do not establish that a screening test causes graduation, that any cutoff should be transferred between academies, or that academy success is equivalent to field readiness.'''
 old1492='''Specialist tactical selection provides a related but distinct context. The week-long tactical police selection study adds information about physical change or completion in a highly selected population [24]. Its role is to show that selection environments impose specific physical demands; it cannot serve as an independent replication of academy prediction, a general occupational injury study, or a prescription for every police service. The combined evidence strengthens the need for task-defined monitoring while preserving the difference between reliable measurement, observed association, and causal intervention effect.'''
 new1492='''Specialist tactical selection provides a related but distinct context. In a small prospective observational study of a five-day specialist tactical police selection course, 18 male candidates started and 11 completed the course; two self-withdrew and five were medically withdrawn [24]. Among completers, body mass (−2.05 kg, p=0.006), right-hand grip strength (−14.48 kg, p<0.001), left-hand grip strength (−14.27 kg, p<0.001), and sit-and-reach flexibility (−6.64 cm, p<0.001) decreased significantly across the selection week, whereas the reported power output, peak jump velocity, and vertical-jump-height outcomes did not show statistically significant deterioration [24]. These findings describe acute within-course changes and do not establish effects on injury risk, operational readiness, selection success, long-term outcomes, or Brazilian tactical police. Its role is to show that selection environments impose specific physical demands; it cannot serve as an independent replication of academy prediction, a general occupational injury study, or a prescription for every police service. The combined evidence strengthens the need for task-defined monitoring while preserving the difference between reliable measurement, observed association, and causal intervention effect.'''
