 human=[{'Hold_ID':'HD-11.2-001','Evidence_ID':'EV-1486','Claim_ID':'RC-EXP3-INT-PHYS-01','Human_Decision':'CONFIRM_BOUNDED_SUPPORT','Human_Reviewer':REVIEWER,'Human_Review_Date':DATE,'Human_Rationale':'Confirmed the authorized prospective cohort result, statistics, bounded wording and prohibited inferences.'},{'Hold_ID':'HD-11.2-002','Evidence_ID':'EV-1492','Claim_ID':'RC-EXP3-INT-PHYS-03','Human_Decision':'CONFIRM_BOUNDED_SUPPORT','Human_Reviewer':REVIEWER,'Human_Review_Date':DATE,'Human_Rationale':'Confirmed participant flow, significant and non-significant outcomes, acute within-course framing and overlap boundary.'}]
