 stats=rd(SRC/'FINAL_STATISTICAL_AUDIT.csv')+[
  {'Sentence_Anchor':'EV-1486 academy cohort','Evidence_ID':'EV-1486','Result_ID':'EV-1486-11F-FT-R01','Statistic':'n=724; 661 graduates; 63 not graduated; OR 9.6 (3.5–26.3), 6.7 (2.5–17.5), 18.4 (6.8–50.2)','Source_Locator':'PMC7781240 | BioC passage 26 | RESULTS paragraph','Audit':'STATISTIC_MATCH'},
  {'Sentence_Anchor':'EV-1492 selection course','Evidence_ID':'EV-1492','Result_ID':'EV-1492-11F-FT2-R01','Statistic':'18 started; 11 completed; 2 self-withdrew; 5 medically withdrawn; body mass −2.05 kg p=0.006; grip/flexibility p<0.001; jump outcomes non-significant','Source_Locator':'PMC7559033 | BioC passage 29 | RESULTS paragraph','Audit':'STATISTIC_MATCH'}]
